import { useState } from "react";
import Papa from "papaparse";

function App() {
  const [page, setPage] = useState("dashboard");
  const [formData, setFormData] = useState({
    duration: "",
    protocol_type: "tcp",
    service: "http",
    flag: "SF",
    src_bytes: "",
    dst_bytes: "",
    logged_in: "",
    count: "",
    srv_count: "",
    serror_rate: "",
    rerror_rate: "",
    dst_host_count: "",
    dst_host_srv_count: "",
    model: "Random Forest"
  });

  const [result, setResult] = useState(null);
  const [uploadedFileName, setUploadedFileName] = useState("");
  const [csvData, setCsvData] = useState([]);

  const models = [
    {
      name: "Decision Tree",
      accuracy: "99.84%",
      precision: "1.00",
      recall: "1.00",
      f1: "1.00"
    },
    {
      name: "Random Forest",
      accuracy: "99.89%",
      precision: "1.00",
      recall: "1.00",
      f1: "1.00"
    },
    {
      name: "Logistic Regression",
      accuracy: "97.23%",
      precision: "0.98",
      recall: "0.96",
      f1: "0.97"
    }
  ];

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const loadNormalSample = () => {
    setFormData({
      ...formData,
      duration: "0",
      protocol_type: "tcp",
      service: "http",
      flag: "SF",
      src_bytes: "181",
      dst_bytes: "5450",
      logged_in: "1",
      count: "8",
      srv_count: "8",
      serror_rate: "0",
      rerror_rate: "0",
      dst_host_count: "255",
      dst_host_srv_count: "255"
    });
  };

  const loadAttackSample = () => {
    setFormData({
      ...formData,
      duration: "0",
      protocol_type: "tcp",
      service: "private",
      flag: "REJ",
      src_bytes: "0",
      dst_bytes: "0",
      logged_in: "0",
      count: "150",
      srv_count: "150",
      serror_rate: "1",
      rerror_rate: "0",
      dst_host_count: "255",
      dst_host_srv_count: "20"
    });
  };

  const handlePredict = () => {
    let score = 0;

    score += Number(formData.serror_rate || 0) * 40;
    score += Number(formData.rerror_rate || 0) * 30;
    score += Number(formData.count || 0) > 100 ? 15 : 0;
    score += formData.flag === "REJ" ? 15 : 0;

    score = Math.min(100, Math.max(1, Math.round(score)));

    let riskLevel = "";
    if (score <= 35) {
      riskLevel = "Low";
    } else if (score <= 60) {
      riskLevel = "Moderate";
    } else {
      riskLevel = "High";
    }

    setResult({
      prediction: riskLevel === "High" ? "Attack" : "Normal",
      risk: riskLevel,
      score: score,
      model: formData.model
    });
  };

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setUploadedFileName(file.name);

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: function (results) {
        setCsvData(results.data.slice(0, 5));
      }
    });
  };

  const getRiskBadgeStyle = (risk) => {
    if (risk === "Low") return styles.lowBadge;
    if (risk === "Moderate") return styles.moderateBadge;
    return styles.highBadge;
  };

  const getPredictionBadgeStyle = (prediction) => {
    return prediction === "Attack" ? styles.attackBadge : styles.normalBadge;
  };

  if (page === "dashboard") {
    return (
      <div style={styles.page}>
        <div style={styles.navbar}>
          <div style={styles.logo}>Threat Detection Dashboard</div>
          <div style={styles.navButtons}>
            <button style={styles.navButton} onClick={() => setPage("dashboard")}>Home</button>
            <button style={styles.navButton} onClick={() => setPage("predict")}>Predict</button>
            <button style={styles.navButton} onClick={() => setPage("upload")}>Upload CSV</button>
          </div>
        </div>

        <div style={styles.heroSection}>
          <p style={styles.tag}>AWS + Machine Learning + Intrusion Analysis</p>
          <h1 style={styles.title}>Cloud-Based Intrusion Detection System</h1>
          <p style={styles.subtitle}>
            Analyze network session data and classify it as normal or attack using machine learning models.
          </p>

          <div style={styles.heroButtons}>
            <button style={styles.primaryButton} onClick={() => setPage("predict")}>
              Predict Session
            </button>
            <button style={styles.secondaryButton} onClick={() => setPage("upload")}>
              Upload CSV
            </button>
          </div>
        </div>

        <div style={styles.statsGrid}>
          <div style={styles.statCard}>
            <p style={styles.statLabel}>Best Model</p>
